const body = $json.body || $json;
const callback = body.callback_query || null;
const message = body.message || body.edited_message || body.channel_post || null;
const isCallback = !!callback;
const isMessage = !!message;
const actionData = String(callback?.data || "");
const parts = actionData.split("|");
const action = String(parts[0] || "");
const subAction = String(parts[1] || "");
const targetId = String(parts.slice(2).join("|") || "");
const chat = callback?.message?.chat || message?.chat || {};
const user = callback?.from || message?.from || {};
const callbackText = String(callback?.message?.text || callback?.message?.caption || "");
const messageText = String(message?.text || message?.caption || "").trim();
const isDmq = action === 'dmq';
const isDmqm = action === 'dmqm';
const isDmqv = action === 'dmqv';
const isDmqvd = action === 'dmqvd';
const callbackOrigin = isDmqvd
  ? 'detail'
  : /DM Queue Detail/i.test(callbackText)
    ? 'detail'
    : /DM Queue View:/i.test(callbackText)
      ? 'view'
      : /Top DM Picks Today/i.test(callbackText)
        ? 'top_picks'
        : isCallback
          ? 'other'
          : 'unknown';

return {
  json: {
    event_type: isCallback ? "callback_query" : (isMessage ? "message" : "unknown"),
    action: isCallback ? action : "dm_inbound",
    content_key: isCallback ? (isDmq || isDmqm || isDmqv || isDmqvd ? targetId : subAction) : "",
    callback_id: callback?.id || "",
    callback_message_id: callback?.message?.message_id || "",
    callback_caption: callback?.message?.caption || "",
    callback_message_text: callbackText,
    callback_origin: callbackOrigin,
    chat_id: String(chat?.id || "7592247598"),
    user_id: String(user?.id || chat?.id || "7592247598"),
    username: user?.username || chat?.username || "",
    first_name: user?.first_name || "",
    last_name: user?.last_name || "",
    message_id: message?.message_id || callback?.message?.message_id || "",
    message_text: messageText,
    dmq_action: isDmq ? subAction : "",
    dmq_user_id: isDmq ? targetId : "",
    dmq_callback: isDmq,
    dmqm_action: isDmqm ? subAction : "",
    dmqm_user_id: isDmqm ? targetId : "",
    dmqm_callback: isDmqm,
    dmqv_action: isDmqv ? subAction : "",
    dmqv_user_id: isDmqv ? targetId : "",
    dmqv_callback: isDmqv,
    dmqvd_user_id: isDmqvd ? targetId : "",
    dmqvd_callback: isDmqvd,
    raw: body
  }
};

const callback = $items("Parse Callback",0,0)[0]?.json || {};
const rows = ($items("Read articles sheet",0,0) || []).map(i => i.json);
const key = String(callback.content_key || "").trim();
const matches = rows.filter(r => String(r.content_key || r.content_id || "").trim() === key);
const row = matches.find(r => String(r.status || r.approval_status || "").toLowerCase() !== "approved") || matches[0] || {};
return [{ json: { ...row, ...callback } }];

const row = $json;
const slot = row.content_type === "feed"
  ? "21:58"
  : (!row.scheduled_slot || row.scheduled_slot === "pending"
      ? (Number(row.score || 0) >= 88 ? "07:30" : (Number(row.score || 0) >= 80 ? "18:30" : "22:20"))
      : row.scheduled_slot);
return {
  json:{
    ...row,
    approval_status:"approved",
    status:"approved",
    time_slot: slot,
    scheduled_slot: slot,
    scheduled_for: slot,
    approved_at:new Date().toISOString()
  }
};

const store = $getWorkflowStaticData('global');
store.test_publish_guard = store.test_publish_guard || {};
const key = String($json.content_key || $json.content_id || '').trim();
if (!key) return [];
if (store.test_publish_guard[key]) return [];
store.test_publish_guard[key] = new Date().toISOString();
return [{ json: { ...$json, test_publish_consumed_at: new Date().toISOString() } }];

const txt = $json.choices?.[0]?.message?.content || '{}';
let parsed={}; try{parsed=JSON.parse(txt)}catch(e){}
const old = $item(0).$node["Find Matching Draft"].json;
const scoreHint = parsed.score_hint || {};
const score = Math.round(((scoreHint.click||old.score||70)+(scoreHint.save||old.score||70)+(scoreHint.debate||old.score||70)+(scoreHint.info||old.score||70)+(scoreHint.instagram_fit||old.score||70))/5);
return {
  json:{...old,...parsed,score,last_action:'regen_contents',approval_status:'pending',updated_at:new Date().toISOString()}
};

const row = $item(0).$node["Find Matching Draft"].json;
const photo = $json.data?.[0]?.url || row.cover_url || '';
return {
  json: {
    ...row,
    chat_id: String(row.chat_id || '7592247598'),
    photo,
    caption:`[REGEN IMAGE]\n${row.final_title || ''}\n\n${row.body || ''}\n\n${row.hashtags || ''}`,
    reply_markup: JSON.stringify({
      inline_keyboard: [
        [
          { text:'? Approve', callback_data:`approve|${row.content_key}` },
          { text:'?? Regen Image', callback_data:`regen_image|${row.content_key}` }
        ],
        [
          { text:'?? Regen Hook', callback_data:`regen_contents|${row.content_key}` },
          { text:'?? Delete', callback_data:`delete|${row.content_key}` }
        ]
      ]
    }),
    content_key: row.content_key,
    cover_url: photo,
    final_title: row.final_title,
    body: row.body,
    hashtags: row.hashtags
  }

};

const txt = $json.choices?.[0]?.message?.content || '{}';
let parsed={}; try{parsed=JSON.parse(txt)}catch(e){}
const row = $item(0).$node["Find Matching Draft"].json;
return {
  json:{...row,...parsed,last_action:'regen_reel',approval_status:'pending',updated_at:new Date().toISOString()}
};

const row = $item(0).$node["Parse Regen Reel"].json;
const photo = $item(0).$node["Regen Reel Cover Image"].json.data?.[0]?.url || row.cover_url || '';
const scenes = Array.isArray(row.scene_json)
  ? row.scene_json
  : (() => { try { return JSON.parse(row.scene_json || '[]'); } catch (e) { return []; } })();
const sceneText = scenes.map((s, idx) => `${idx + 1}. ${s.caption || ''}`).join('\n');
return {
  json: {
    ...row,
    chat_id: String(row.chat_id || '7592247598'),
    photo,
    caption:
      `[REGEN REEL]\n${row.final_title || ''}\n\n` +
      `${row.body || ''}\n\n` +
      `${row.hashtags || ''}\n\n` +
      `??: ${row.music_tag || ''}\n\n` +
      `??:\n${sceneText}`,
    reply_markup: JSON.stringify({
      inline_keyboard: [
        [
          { text: '? Approve', callback_data: `approve|${row.content_key}` },
          { text: '?? Regen Reel', callback_data: `regen_reel|${row.content_key}` }
        ],
        [
          { text: '?? Regen Image', callback_data: `regen_image|${row.content_key}` },
          { text: '?? Delete', callback_data: `delete|${row.content_key}` }
        ]
      ]
    })
  }

};

return {
  json:{...$json, approval_status:"deleted", status:"deleted", deleted_at:new Date().toISOString()}
};

return {
  json: {
    chat_id: String($json.chat_id || '7592247598'),
    text:
      `[APPROVED]\n${$json.final_title || ''}\n\n` +
      `status: approved\n` +
      `scheduled_slot: ${$json.scheduled_slot || $json.scheduled_for || ''}\n` +
      `content_key: ${$json.content_key || ''}`
  }

};

const row = $json;
const base = $item(0).$node["Find Matching Draft"].json;
const photo = row.cover_url || row.image_url || base.cover_url || base.image_url || '';

return {
  json: {
    ...row,
    chat_id: String(row.chat_id || '7592247598'),
    photo,
    caption:
      `[REGEN CONTENTS]\n${row.final_title || ''}\n\n` +
      `${row.body || ''}\n\n` +
      `${row.hashtags || ''}`,
    reply_markup: JSON.stringify({
      inline_keyboard: [
        [
          { text: '? Approve', callback_data: `approve|${row.content_key}` },
          { text: '?? Regen Hook', callback_data: `regen_contents|${row.content_key}` }
        ],
        [
          { text: '?? Regen Image', callback_data: `regen_image|${row.content_key}` },
          { text: '?? Regen Reel', callback_data: `regen_reel|${row.content_key}` }
        ],
        [
          { text: '?? Delete', callback_data: `delete|${row.content_key}` }
        ]
      ]
    })
  }
};

return {
  json: {
    chat_id: String($json.chat_id || '7592247598'),
    text:
      `[DELETED]\n${$json.final_title || ''}\n\n` +
      `??: deleted\n` +
      `content_key: ${$json.content_key || ''}`
  }

};

const inbound = $items("Append Telegram DM Action", 0, 0)[0]?.json || {};
const stateRows = $input.all().map(i => i.json).filter(r => String(r.record_type || '') === 'dm_state');

const userId = String(inbound.user_id || inbound.chat_id || 'unknown').trim() || 'unknown';
const latestMessage = String(inbound.message_text || inbound.callback_caption || '').trim();
const userDisplayName = String(inbound.username || inbound.first_name || inbound.last_name || userId).trim() || userId;
const normalized = latestMessage.toLowerCase();
const now = new Date();
const nowIso = now.toISOString();

const currentUserRows = stateRows.filter(r => String(r.user_id || '') === userId);
const dm_state_conflict_count = currentUserRows.length;
const dm_state_row_conflict = dm_state_conflict_count > 1;
const previous = currentUserRows
  .sort((a, b) => new Date(a.dm_state_updated_at || a.last_interaction_at || a.updated_at || a.timestamp || 0).getTime() - new Date(b.dm_state_updated_at || b.last_interaction_at || b.updated_at || b.timestamp || 0).getTime())
  .slice(-1)[0] || {};

const keywordGroups = {
  b2b: ['留ㅼ옣', '?댁쁺', '?ш퀬', '留덉쭊', '湲곗?', '諛쒖＜', '?뚯쟾', '吏꾩뿴', '?먮ℓ', '?먰빐', '援ъ“', '由ъ뒪??, 'shop', 'store', 'operation', 'inventory', 'margin', 'order', 'turnover', 'display', 'sales', 'loss', 'structure', 'risk'],
  deeper: ['?ш퀬', '留덉쭊', '湲곗?', '諛쒖＜', '?뚯쟾', '援ъ“', '由ъ뒪??, 'inventory', 'margin', 'structure', 'risk', 'operation', 'operations'],
  repeat: ['?ㅼ떆', '怨꾩냽', '諛섎났', '??, 'again', 'repeat', 'still']
};

const matched = new Set();
for (const key of keywordGroups.b2b) {
  if (normalized.includes(String(key).toLowerCase())) matched.add(key);
}
for (const key of keywordGroups.repeat) {
  if (normalized.includes(String(key).toLowerCase())) matched.add(key);
}

let scoreDelta = 0;
if (matched.size > 0) scoreDelta += matched.size * 2;
if (keywordGroups.deeper.some(k => normalized.includes(String(k).toLowerCase()))) scoreDelta += 2;
if (/[?竊?/.test(latestMessage)) scoreDelta += 1;
if (normalized.length > 20) scoreDelta += 1;
if (String(previous.last_message || '') !== latestMessage && previous.last_message) scoreDelta += 1;
if (Number(previous.interaction_count || 0) > 0) scoreDelta += 1;

const interaction_count = Number(previous.interaction_count || 0) + 1;
const b2b_score = Number(previous.b2b_score || 0) + scoreDelta;
const previousLeadType = String(previous.lead_type || 'lead_general');

const lead_type = b2b_score >= 8 && interaction_count >= 2
  ? 'lead_b2b_hot'
  : b2b_score >= 3
    ? 'lead_b2b_candidate'
    : 'lead_general';

const stage1CooldownMs = 30 * 60 * 1000;
const candidateCooldownMs = 60 * 60 * 1000;
const hotCooldownMs = 60 * 60 * 1000;
const softCooldownMs = 60 * 60 * 1000;
const alertCooldownMs = 12 * 60 * 60 * 1000;

const prevInteractionAt = previous.last_interaction_at ? Date.parse(previous.last_interaction_at) : 0;
const prevHotAlertAt = previous.last_hot_alert_at ? Date.parse(previous.last_hot_alert_at) : 0;
const sincePrev = prevInteractionAt ? (now.getTime() - prevInteractionAt) : Number.POSITIVE_INFINITY;

const should_send_stage_1 = !prevInteractionAt || sincePrev >= stage1CooldownMs;
const should_send_filter_question = should_send_stage_1 && (!prevInteractionAt || sincePrev >= stage1CooldownMs);
const should_send_candidate_reply = lead_type === 'lead_b2b_candidate' && (!prevInteractionAt || sincePrev >= candidateCooldownMs);
const should_send_hot_reply = lead_type === 'lead_b2b_hot' && (!prevInteractionAt || sincePrev >= hotCooldownMs);
const should_send_soft_offer = lead_type === 'lead_b2b_hot' && should_send_hot_reply && (!prevInteractionAt || sincePrev >= softCooldownMs);
const should_alert_hot_lead = lead_type === 'lead_b2b_hot' && (previousLeadType !== 'lead_b2b_hot' || !prevHotAlertAt || (now.getTime() - prevHotAlertAt) >= alertCooldownMs);

const last_reply_stage = should_send_soft_offer
  ? 'soft_offer'
  : should_send_hot_reply
    ? 'hot_escalation'
    : should_send_candidate_reply
      ? 'candidate_depth'
      : should_send_filter_question
        ? 'filter_question'
        : should_send_stage_1
          ? 'stage_1'
          : String(previous.last_reply_stage || 'none');

const dm_reply_stage = last_reply_stage;
const soft_offer_eligible = lead_type === 'lead_b2b_hot';
const last_hot_alert_at = should_alert_hot_lead ? nowIso : String(previous.last_hot_alert_at || '');
const dm_keywords_matched = Array.from(matched);
const dm_b2b_keyword_hits = dm_keywords_matched.filter(k => keywordGroups.b2b.includes(k)).length;

const stage1Templates = [
  '?닿굅 洹몃깷 ?뺣낫濡?蹂대㈃\n怨꾩냽 ?由쎈땲??
\n吏湲?蹂댁떊 ?댁슜\n寃됰쭔 怨듦컻?쒓굅?쇱꽌\n\n湲곗? ?놁씠 蹂대㈃\n?ㅽ엳???먰빐 ?볦엯?덈떎',
  '?닿굔 洹몃깷 ?쒗뭹 ?뺣낫媛 ?꾨땲??
蹂대뒗 湲곗? 臾몄젣?낅땲??
\n湲곗? ?놁쑝硫?
怨꾩냽 ?由ш쾶 蹂닿쾶 ?⑸땲??
\n?ш린?쒕????대? 媛덈┰?덈떎'
];

const filterQuestions = [
  '吏湲?留ㅼ옣 湲곗??쇰줈 蹂댁떆?붽굔媛??
?꾨땲硫?洹몃깷 ?뺣낫濡?蹂대뒗嫄닿???,
  '?닿굅 ?ㅼ젣濡??댁쁺???곗떎 ?앷컖 ?덉쑝?좉???
?꾨땲硫?李멸퀬?⑹씠?몄슂',
  '吏湲?蹂댁떆??湲곗???
媛쒖씤?⑹씤吏 ?댁쁺?⑹씤吏???곕씪\n?댁꽍???щ씪吏묐땲??
];

const candidateReplies = [
  '?닿굔 怨듦컻 湲곗??쇰줈 蹂대㈃\n?덈컲? ?由ш쾶 ?댄빐?⑸땲??
\n?뱁엳 ?ш퀬??留덉쭊 履쎌?\n?꾩쟾???ㅻⅨ ?섍린?쇱꽌\n\n?ш린???遺遺?留됲옓?덈떎',
  '?닿굔 蹂대뒗 ?щ엺???곕씪\n媛숈? ?댁슜???꾩쟾???щ씪吏묐땲??
\n?댁쁺 履쎌쑝濡??ㅼ뼱媛硫?
湲곗? ?먯껜媛 諛붾앸땲??
\n?遺遺??ш린???由쎈땲??
];

const hotReplies = [
  '?닿굔 ?뺣━ ?덈맂 ?곹깭濡?蹂대㈃\n?ㅽ엳???꾪뿕?⑸땲??
\n蹂댄넻 ?ш린?쒕???
援ъ“瑜??곕줈 ?섎닠??遊낅땲??,
  '???④퀎遺?곕뒗\n洹몃깷 怨듦컻 ?뺣낫泥섎읆 蹂대㈃ ???⑸땲??
\n?ш린?쒕??곕뒗\n湲곗??섍퀬 援ъ“媛 ??以묒슂?⑸땲??
];

const softOffers = [
  '?닿굔 怨듦컻濡?? ???덈뒗 踰붿쐞媛 ?꾨땲?쇱꽌\n\n?꾩슂?섏떆硫?
湲곗??대옉 援ъ“???곕줈 ?뺣━?대뱶由쎈땲??,
  '?ш린遺?곕뒗 怨듦컻?뺤쑝濡??硫?
?ㅽ엳???쒓끝?⑸땲??
\n?먰븯?쒕㈃\n湲곗??섍퀬 援ъ“留??곕줈 ?뺣━?대뱶由??섎뒗 ?덉뒿?덈떎'
];

const stage1Index = interaction_count % stage1Templates.length;
const filterIndex = interaction_count % filterQuestions.length;
const candidateIndex = b2b_score % candidateReplies.length;
const hotIndex = interaction_count % hotReplies.length;
const softIndex = b2b_score % softOffers.length;

const repeatedOperationalDepth = interaction_count >= 2 && dm_b2b_keyword_hits >= 2 && keywordGroups.deeper.some(k => normalized.includes(String(k).toLowerCase())) && sincePrev < candidateCooldownMs;
const softOfferFollowup = soft_offer_eligible && String(previous.last_reply_stage || '') === 'soft_offer' && interaction_count >= 3;
const repeatedHotBehavior = lead_type === 'lead_b2b_hot' && !should_alert_hot_lead && previousLeadType === 'lead_b2b_hot';
const manualTakeoverReasons = [];
if (lead_type === 'lead_b2b_hot') manualTakeoverReasons.push('hot lead');
if (dm_state_row_conflict) manualTakeoverReasons.push('conflict');
if (repeatedHotBehavior) manualTakeoverReasons.push('hot alert blocked');
if (repeatedOperationalDepth) manualTakeoverReasons.push('deep operational');
if (softOfferFollowup) manualTakeoverReasons.push('soft offer follow-up');
const should_manual_takeover = lead_type === 'lead_b2b_hot' || dm_state_row_conflict || repeatedHotBehavior || repeatedOperationalDepth || softOfferFollowup;
const manual_takeover_priority = (dm_state_row_conflict && lead_type === 'lead_b2b_hot') || repeatedOperationalDepth || softOfferFollowup
  ? 'high'
  : lead_type === 'lead_b2b_hot'
    ? 'medium'
    : dm_state_row_conflict || repeatedHotBehavior
      ? 'medium'
      : 'low';

const dm_last_triggered_replies = [
  should_send_stage_1 ? 'stage_1' : '',
  should_send_filter_question ? 'filter_question' : '',
  should_send_candidate_reply ? 'candidate_reply' : '',
  should_send_hot_reply ? 'hot_reply' : '',
  should_send_soft_offer ? 'soft_offer' : ''
].filter(Boolean).join('|') || 'none';
const dm_last_blocked_replies = [
  !should_send_stage_1 ? 'stage_1' : '',
  !should_send_filter_question ? 'filter_question' : '',
  lead_type === 'lead_b2b_candidate' && !should_send_candidate_reply ? 'candidate_reply' : '',
  lead_type === 'lead_b2b_hot' && !should_send_hot_reply ? 'hot_reply' : '',
  lead_type === 'lead_b2b_hot' && !should_send_soft_offer ? 'soft_offer' : ''
].filter(Boolean).join('|') || 'none';
const dm_last_throttle_reason = !should_send_stage_1
  ? 'stage_1 cooldown'
  : !should_send_filter_question
    ? 'filter cooldown'
    : lead_type === 'lead_b2b_candidate' && !should_send_candidate_reply
      ? 'candidate cooldown'
      : lead_type === 'lead_b2b_hot' && !should_send_hot_reply
        ? 'hot cooldown'
        : lead_type === 'lead_b2b_hot' && !should_send_soft_offer
          ? 'soft offer cooldown'
          : 'none';
const dm_last_manual_takeover_reason = manualTakeoverReasons.slice(0, 3).join('|') || 'none';
const dm_last_decision_at = nowIso;
const dm_decision_trace = `lead=${lead_type};sent=${dm_last_triggered_replies};blocked=${dm_last_blocked_replies};manual=${should_manual_takeover ? manual_takeover_priority : 'off'}`;

const dm_state_conflict_latest_ids_or_indexes = JSON.stringify(
  currentUserRows.map(r => String(r.dm_state_updated_at || r.last_interaction_at || r.updated_at || r.timestamp || '')).filter(Boolean)
);
const last_dm_state_conflict_alert_at = String(previous.last_dm_state_conflict_alert_at || '');
const should_alert_dm_state_conflict = dm_state_row_conflict && (!last_dm_state_conflict_alert_at || (now.getTime() - Date.parse(last_dm_state_conflict_alert_at)) >= (24 * 60 * 60 * 1000));
const dm_state_needs_cleanup = dm_state_row_conflict;
const dm_state_conflict_alert_text = `?? dm_state conflict detected
- user: ${userDisplayName}
- matched_rows: ${dm_state_conflict_count}
- latest_message: ${latestMessage.slice(0, 120)}`;

const last_manual_takeover_alert_at = String(previous.last_manual_takeover_alert_at || '');
const should_alert_manual_takeover = should_manual_takeover && (!last_manual_takeover_alert_at || (now.getTime() - Date.parse(last_manual_takeover_alert_at)) >= (24 * 60 * 60 * 1000));
const manual_takeover_alert_text = `?? Manual takeover suggested
- user: ${userDisplayName}
- lead_type: ${lead_type}
- priority: ${manual_takeover_priority}
- latest_message: ${latestMessage.slice(0, 120)}`;

const dm_last_send_success = true;
const dm_last_send_failed_step = '';
const dm_last_send_failed_at = '';
const dm_last_send_error_summary = '';
const dm_health_status = dm_state_row_conflict || should_manual_takeover ? 'review' : 'healthy';
const dm_needs_review = dm_health_status !== 'healthy';
const dm_last_failure_type = dm_state_row_conflict ? 'conflict' : 'none';
const dm_last_failure_alert_at = String(previous.last_dm_failure_alert_at || '');
const should_alert_dm_failure = false;
const dm_failure_alert_text = `?? DM flow issue
- user: ${userDisplayName}
- failed_step: none
- health: ${dm_health_status}
- latest_message: ${latestMessage.slice(0, 120)}`;

const alertText = `?? B2B HOT ?? ??
- user: ${userDisplayName}
- interaction_count: ${interaction_count}
- b2b_score: ${b2b_score}
- latest_message: ${latestMessage.slice(0, 120)}`;

return [{
  json: {
    ...inbound,
    record_type: 'dm_state',
    user_id: userId,
