const manualPriority = String(state.manual_takeover_priority || 'low');
const archived = String(existing.queue_status || '').trim().toLowerCase() === 'archived';
const strongSignal = isHot || hasManual || hasFailure || needsCleanup;

if (!strongSignal) return [];

let reviewReason = 'hot_lead';
if (hasManual && hasFailure) reviewReason = 'takeover_plus_failure';
else if (isHot && hasFailure && needsCleanup) reviewReason = 'hot_plus_conflict';
else if (isHot && hasFailure) reviewReason = 'hot_plus_failure';
else if (hasFailure) reviewReason = 'dm_failure';
else if (needsCleanup && isHot) reviewReason = 'hot_plus_conflict';
else if (needsCleanup) reviewReason = 'state_conflict';
else if (hasManual) reviewReason = 'manual_takeover';
else if (isHot) reviewReason = 'hot_lead';

let reviewPriority = 'low';
if ((isHot && (hasFailure || needsCleanup)) || (hasManual && manualPriority === 'high')) reviewPriority = 'urgent';
else if (isHot || manualPriority === 'high') reviewPriority = 'high';
else if (manualPriority === 'medium' || hasReview || hasFailure) reviewPriority = 'medium';
else if (needsCleanup) reviewPriority = 'low';

const signalAt = String(state.last_interaction_at || state.dm_state_updated_at || state.dm_last_decision_at || nowIso).trim();
const signalTime = new Date(signalAt).getTime();
const ageHours = Number.isFinite(signalTime) ? (Date.now() - signalTime) / 36e5 : 0;
let queueSortScore = 0;
if (isHot) queueSortScore += 60;
if (manualPriority === 'high') queueSortScore += 40;
else if (manualPriority === 'medium') queueSortScore += 25;
if (hasReview) queueSortScore += 20;
if (hasFailure) queueSortScore += 18;
if (needsCleanup) queueSortScore += 15;
if (String(state.dm_health_status || 'healthy') !== 'healthy') queueSortScore += 12;
if (String(state.soft_offer_eligible) === 'true') queueSortScore += 8;
if (Number.isFinite(ageHours)) {
  if (ageHours <= 1) queueSortScore += 15;
  else if (ageHours <= 6) queueSortScore += 10;
  else if (ageHours <= 24) queueSortScore += 5;
}
queueSortScore += Math.min(10, Number(state.interaction_count || 0) * 1.5);

let queueStatus = String(existing.queue_status || '').trim().toLowerCase() || 'open';
let archiveReason = String(existing.archive_reason || '').trim();
let archivedAt = String(existing.archived_at || '').trim();
