let reopenReason = String(existing.reopen_reason || 'none').trim() || 'none';
if (shouldReopen) {
  queueStatus = 'open';
  if (hasFailure) {
    reviewReason = 'reopened_failure';
    reopenReason = 'new_dm_failure';
  } else if (isHot || hasManual || needsCleanup) {
