  + (responseWindowStatus === 'immediate' ? 35 : responseWindowStatus === 'today' ? 20 : responseWindowStatus === 'later' ? 5 : 0)
  + (operatorLoadHint === 'act_now' ? 25 : operatorLoadHint === 'review_batch' ? 15 : operatorLoadHint === 'monitor_only' ? 5 : 0)
  + (engagementStatus === 'active' ? 12 : engagementStatus === 'cooling' ? 6 : 0)
);

const operatorTodayHint = todayActionBucket === 'closed'
  ? 'no_action_today'
